<script setup lang="ts">
import { computed,onMounted } from 'vue';import { RouterLink,RouterView,useRoute,useRouter } from 'vue-router';import { MessageSquareText,Library,Leaf,Brain,LogOut,SlidersHorizontal,ShieldCheck } from 'lucide-vue-next';import { useAppStore } from './store';import UploadDrawer from './components/UploadDrawer.vue'
const store=useAppStore(),route=useRoute(),router=useRouter(),authPage=computed(()=>route.path==='/login')
onMounted(async()=>{await store.bootstrap();if(!store.user&&route.path!=='/login')router.replace('/login');else if(store.user&&route.path==='/login')router.replace('/chat')})
async function logout(){await store.logout();router.replace('/login')}
</script>
<template><div v-if="!store.bootstrapped" class="auth-page">正在恢复登录状态…</div><RouterView v-else-if="authPage"/><div v-else-if="store.user" class="shell"><aside class="rail"><div class="brand"><Leaf :size="23"/><span>Learning Q&A</span></div><nav><RouterLink to="/chat"><MessageSquareText/><span>对话</span></RouterLink><RouterLink to="/documents"><Library/><span>资料</span></RouterLink><RouterLink to="/memories"><Brain/><span>记忆</span></RouterLink><RouterLink v-if="store.user.role==='admin'" to="/admin"><ShieldCheck/><span>管理</span></RouterLink><RouterLink v-if="store.capabilities?.features.model_center" to="/models"><SlidersHorizontal/><span>模型</span></RouterLink></nav><div class="identity"><span>{{store.user.username}}</span><small>{{store.user.role==='admin'?'平台管理员':'普通用户'}}</small><button class="icon" aria-label="退出登录" @click="logout"><LogOut/></button></div></aside><main><div v-if="store.error" class="global-error" role="alert">{{store.error}}</div><RouterView/></main><UploadDrawer/></div><main v-else class="auth-page">正在跳转到登录页…</main></template>
